API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(AWS_API_Gateway_REST, "AWS API Gateway (REST)", "AWS API Gateway (REST)", "Manages ingress routing, rate limiting, and JWT validation within cost limits.")
    Component(Token_Masking_Engine, "Token Masking Engine", "Rust Native Plugin / Edge Middleware", "Executes zero-cold-start, in-memory token masking to meet <50ms P99 latency at 3,000 RPS.")
}

Rel(AWS_API_Gateway_REST, Token_Masking_Engine, "Invokes in-memory request sanitization", "Synchronous Edge Execution")

@enduml

Network Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(network_load_balancer, "Network Load Balancer") {
    Component(TLS_Termination, "TLS Termination", "AWS Network Load Balancer TLS Listener", "Handles Layer 4/7 edge routing with TLS 1.3/1.2 ciphers and terminates incoming mTLS connections from the API Gateway.")
    Component(Health_Check, "Health Check", "AWS NLB Target Group Health Checks", "Monitors the health and availability of downstream Fraud Scoring Engine instances.")
}

Rel(TLS_Termination, Health_Check, "Validates target availability before forwarding traffic", "")

@enduml

Feature/Rule Store & Hot Case Data.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(feature_rule_store_hot_case_data, "Feature/Rule Store & Hot Case Data") {
    Component(Feature_Store, "Feature Store", "Amazon DynamoDB", "Stores low-latency features for real-time fraud scoring.")
    Component(DAX_Accelerator, "DAX Accelerator", "Amazon DynamoDB Accelerator (DAX)", "Provides in-memory caching for DynamoDB to meet <50ms P99 latency SLA.")
    Component(Hot_Case_Data_Store, "Hot Case Data Store", "Amazon DynamoDB", "Persists hot case data for ongoing fraud investigations.")
    Component(Rule_Distribution_Provider, "Rule Distribution Provider", "AWS AppConfig", "Distributes scoring rules with zero downtime and built-in schema validation.")
}

Rel(DAX_Accelerator, Feature_Store, "Caches and queries low-latency feature lookups", "")
Rel(Rule_Distribution_Provider, Feature_Store, "Supplies configuration rules", "")

@enduml
